text(await tools.apply_patch("*** Begin Patch
*** Add File: outputs/DeepSeek桌面版/Launch.ps1
+param([switch]$CheckOnly)
+$ErrorActionPreference = 'Stop'
+$appDir = Join-Path $env:LOCALAPPDATA 'DeepSeekHarnessDesktop'
+$node = 'F:\node.js\node.exe'
+$entry = Join-Path $appDir 'runtime\node_modules\@deepseek-ai\dsh\lib\bin.js'
+$log = Join-Path $appDir 'server.log'
+$errLog = Join-Path $appDir 'server-error.log'
+$stateFile = Join-Path $appDir 'server.json'
+$mutex = New-Object Threading.Mutex($false, 'Local\DeepSeekHarnessDesktopLaunch')
+$locked = $false
+try {
+    $locked = $mutex.WaitOne(120000)
+    if (-not $locked) { throw 'Another launch is still in progress. Please try again shortly.' }
+    $env:PATH = 'F:\node.js;' + [Environment]::GetEnvironmentVariable('Path','User') + ';' + [Environment]::GetEnvironmentVariable('Path','Machine')
+    $env:DSH_HOME = Join-Path $env:USERPROFILE '.dsh'
+    $url = $null
+    if (Test-Path -LiteralPath $stateFile) {
+        try {
+            $state = Get-Content -LiteralPath $stateFile -Raw | ConvertFrom-Json
+            $proc = Get-Process -Id $state.pid -ErrorAction Stop
+            if ($proc.Path -eq $node -and $proc.StartTime.ToUniversalTime().Ticks.ToString() -eq $state.started) {
+                $response = Invoke-WebRequest -Uri $state.url -UseBasicParsing -TimeoutSec 4
+                if ($response.StatusCode -eq 200) { $url = $state.url }
+            }
+        } catch { $url = $null }
+    }
+    if (-not $url) {
+        if (-not (Test-Path -LiteralPath $entry)) { throw 'DeepSeek runtime is missing.' }
+        $proc = Start-Process -FilePath $node -ArgumentList @(('"' + $entry + '"'), 'web', '--no-open', '--host', '127.0.0.1', '--port', '0') -WorkingDirectory $env:USERPROFILE -WindowStyle Hidden -RedirectStandardOutput $log -RedirectStandardError $errLog -PassThru
+        $deadline = (Get-Date).AddSeconds(100)
+        while ((Get-Date) -lt $deadline) {
+            $proc.Refresh()
+            if ($proc.HasExited) { throw ('DeepSeek could not start. See ' + $errLog) }
+            if (Test-Path -LiteralPath $log) {
+                $content = Get-Content -LiteralPath $log -Raw
+                if ($content -match 'dsh web: (http://(?:127\.0\.0\.1|localhost):\d+/[^\s\x1b]*)') {
+                    $candidate = $Matches[1]
+                    try {
+                        $response = Invoke-WebRequest -Uri $candidate -UseBasicParsing -TimeoutSec 3
+                        if ($response.StatusCode -eq 200) { $url = $candidate; break }
+                    } catch {}
+                }
+            }
+            Start-Sleep -Milliseconds 500
+        }
+        if (-not $url) { throw ('Startup timed out. See ' + $errLog) }
+        @{pid=$proc.Id; started=$proc.StartTime.ToUniversalTime().Ticks.ToString(); url=$url} | ConvertTo-Json | Set-Content -LiteralPath $stateFile -Encoding UTF8
+    }
+    if ($CheckOnly) { Write-Output 'DeepSeek desktop: server ready (HTTP 200).'; exit 0 }
+    $browser = 'C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe'
+    if (-not (Test-Path -LiteralPath $browser)) { $browser = 'C:\Program Files\Google\Chrome\Application\chrome.exe' }
+    if (-not (Test-Path -LiteralPath $browser)) { throw 'Microsoft Edge or Google Chrome is required.' }
+    Start-Process -FilePath $browser -ArgumentList @('--app="' + $url + '"', '--new-window')
+} catch {
+    $_ | Out-String | Set-Content -LiteralPath (Join-Path $appDir 'launcher-error.log') -Encoding UTF8
+    if ($CheckOnly) { throw }
+    Add-Type -AssemblyName System.Windows.Forms
+    [System.Windows.Forms.MessageBox]::Show($_.Exception.Message, 'DeepSeek Harness', 'OK', 'Error') | Out-Null
+} finally {
+    if ($locked) { $mutex.ReleaseMutex() }
+    $mutex.Dispose()
+}
*** End Patch"));

